// TH16 v1.00a Stage 1 boss, first nonspell.
// Source: st01bs.ecl.txt Boss1:51-78 (entry); deps Boss1_at:80-112, Boss1_at2:114-173.
// Entry state (context only) st01bs.ecl.txt Boss:8-49:
//   movePos(0,128), moveLimit(0,128,280,64), setHurtbox(40,40), setHitbox(48,48), no mirror.
// Omitted per approved policy: diffI($A..) unused local, timerReset/setInterrupt (phase shell),
// lifeMarker/stars/dropSeason, all anm*/playSound, ANIM birth deceleration window and
// the SPEEDUP-ex birth presentation flag. ANIM birth back-off (position -= 4*velocity) is kept.

const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;

// TH16 type aliases (bullets.md/bullet-types.md), copied for this card.
const TH16_BALL: int = 416;   // source etSprite(1, 4, 6) in Boss1_at2
const TH16_RICE: int = 480;   // source etSprite(0, 8, 10) in Boss1_at
const COLOR_BALL: int = 6;
const COLOR_RICE: int = 10;

// ---------------------------------------------------------------------------
// Movement: source moveRand(60, 4, 1.0) under moveLimit(0,128,280,64).
// Tool recipe (movement.md) adapted to the 280-wide limit: inner region x=+-70,
// y=112..144; actual clamp x=+-140, y=96..160. Speed is linear 1 -> 0 over 60 ticks.
// self int0 = next-step counter; self fx0/fx1 = logical (cos, sin) of the direction.
// ---------------------------------------------------------------------------
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

sub move_rand() {
    // Source 412 direction selection; values are unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}

// ---------------------------------------------------------------------------
// Boss1_at (dependency): fixed-direction fan, 6 lanes x 3 layers, 10 frames apart.
// etAim(0,1); etSprite(0,8,10); etCount(0,6,I0=3); etAngle(0,90deg,delta);
// etSpeed(0,s0,3.0) -> layer speeds s0 + (3-s0)*q/2; delta starts 76deg, -7deg/shot.
// Shots: E 7, N 10, H 11, L 11. s0: E 1.5, N 2.5, H 2.5, L 4.1.
// ---------------------------------------------------------------------------
async sub boss1_at() {
    var shots: int = 7;
    var s0: fx = 1.5fx;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { shots = 10; s0 = 2.5fx; }
    else if rank == RANK_HARD { shots = 11; s0 = 2.5fx; }
    else if rank == RANK_LUNATIC { shots = 11; s0 = 4.1fx; }

    var delta: angle = 76deg;   // source 1.3264502 rad
    for k in 0..shots {
        var db: int = delta as int;
        for q in 0..3 {
            var spd: fx = s0 + (3fx - s0) * q / 2;
            for i in 0..6 {
                // mode1 fan: F = (-1)^i * (floor(i/2)+0.5) * delta
                var m: int = (i / 2) * 2 + 1;
                var off: int = (m * db) / 2;
                if i % 2 != 0 { off = -off; }
                var ba: angle = 90deg + (off as angle);
                var ca: fx = cos(ba);
                var sa: fx = sin(ba);
                // ANIM a=1 keeps position -= 4*velocity at birth.
                var px: fx = $self_x - 4fx * spd * ca;
                var py: fx = $self_y - 4fx * spd * sa;
                _ = fire(TH16_RICE, COLOR_RICE, px, py, spd, ba, none, none);
            }
        }
        wait(10);
        delta = delta - 7deg;
    }
}

// ---------------------------------------------------------------------------
// Boss1_at2 (dependency): long async emitter.
//   wait 60; etNew(1); etAim(1,3); etSprite(1,4,6); etCount(1,1,layers);
//   etAngle(1,90deg,2deg); etSpeed(1,s0,0.8); floatTime(0,C,0,1200,start,goal).
// Native TH16 opcode91 writes start immediately; frames=0 disables later writeback.
// Layers/s0/gap: E 1/1.0/60, N 1/1.0/60, H 1/2.0/30, L 2/2.0/30.
// Per iteration: circlePos(RANDRAD, RANDF*128), etOffset(A, 0.4*B), etOn, wait(int(C)).
// 6000-iteration cap. Keep the source's constant interval; do not swap frames/mode.
// ---------------------------------------------------------------------------
async sub boss1_at2() {
    var layers: int = 1;
    var s0: fx = 1fx;
    var gap: int = 60;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { layers = 1; s0 = 1fx; gap = 60; }
    else if rank == RANK_HARD { layers = 1; s0 = 2fx; gap = 30; }
    else if rank == RANK_LUNATIC { layers = 2; s0 = 2fx; gap = 30; }

    wait(60);
    var e: int = 6000;
    while e > 0 {
        e = e - 1;
        // circlePos(%A,%B,RANDRAD,RANDF*128); etOffset(1, A, B*0.4)
        var th: int = rand(65536) - 32768;
        var u: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;
        var rad: fx = u * 128fx;
        var thang: angle = th as angle;
        var ox: fx = rad * cos(thang);
        var oy: fx = rad * sin(thang) * 0.4fx;
        for q in 0..layers {
            var spd: fx = s0;
            if layers > 1 { spd = s0 + (0.8fx - s0) * q / (layers - 1); }
            var qoff: angle = (q * 364) as angle;   // source 2deg per layer
            var ba: angle = 90deg + qoff;
            var ca: fx = cos(ba);
            var sa: fx = sin(ba);
            var px: fx = $self_x + ox - 4fx * spd * ca;
            var py: fx = $self_y + oy - 4fx * spd * sa;
            _ = fire(TH16_BALL, COLOR_BALL, px, py, spd, ba, none, none);
        }
        wait(gap);
    }
}

// ---------------------------------------------------------------------------
// Boss1 entry: wait 60, then spawn both async emitters; loop spawn + moveRand.
// ---------------------------------------------------------------------------
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);   // source setHurtbox(40,40) -> radius 20
    set_hitbox(24fx);    // source setHitbox(48,48)  -> radius 24
    wait(60);
    spawn boss1_at2();
    spawn boss1_at();
    loop {
        wait(120);
        move_rand();
        card_wait(60);
        spawn boss1_at();
    }
}

// ---------------------------------------------------------------------------
// Validation shell: control owns the phase timer and has no body; the real
// boss carries the source body/hurt boxes and movement.
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
